#!/usr/bin/env python3
"""Bidirectional Key-Segment stream engine.

Implements:
  main.py compile          - read config JSON on stdin, emit compiled program JSON
  main.py stream <prog>    - read requests per line, emit one JSON response per line
"""
import sys
import json
import heapq
from bisect import bisect_right

sys.set_int_max_str_digits(8192)

INT32_MAX = 2**31 - 1
INT32_MIN = -2**31
TIME_MAX = 2**53 - 1


# ---------------------------------------------------------------------------
# JSON helpers
# ---------------------------------------------------------------------------
class BadJSON(Exception):
    pass


def _reject_const(x):
    raise BadJSON("non-finite constant")


def _no_dup(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise BadJSON("duplicate key")
        d[k] = v
    return d


def parse_json_text(text):
    return json.loads(text, object_pairs_hook=_no_dup, parse_constant=_reject_const)


def is_int(x):
    return type(x) is int


# ---------------------------------------------------------------------------
# Configuration validation (compile)
# ---------------------------------------------------------------------------
class ConfigError(Exception):
    pass


def _req_int(x, lo, hi):
    if not is_int(x):
        raise ConfigError()
    if x < lo or x > hi:
        raise ConfigError()
    return x


def validate_config(cfg):
    if not isinstance(cfg, dict):
        raise ConfigError()
    if set(cfg.keys()) != {"version", "idle_timeout", "packet_limit",
                           "prefix_width", "rules", "fallback"}:
        raise ConfigError()

    if not is_int(cfg["version"]) or cfg["version"] != 1:
        raise ConfigError()

    idle_timeout = _req_int(cfg["idle_timeout"], 0, 10**9)
    packet_limit = _req_int(cfg["packet_limit"], 1, 10**9)
    W = _req_int(cfg["prefix_width"], 1, 32)

    rules_raw = cfg["rules"]
    if not isinstance(rules_raw, list):
        raise ConfigError()
    if len(rules_raw) > 2048:
        raise ConfigError()

    rules = []
    seen_ids = set()
    total_positions = 0
    for r in rules_raw:
        if not isinstance(r, dict):
            raise ConfigError()
        if set(r.keys()) != {"id", "class", "priority", "ranges"}:
            raise ConfigError()
        rid = _req_int(r["id"], 0, INT32_MAX)
        rcls = _req_int(r["class"], 0, 65535)
        rprio = _req_int(r["priority"], INT32_MIN, INT32_MAX)
        if rid in seen_ids:
            raise ConfigError()
        seen_ids.add(rid)
        ranges_raw = r["ranges"]
        if not isinstance(ranges_raw, list):
            raise ConfigError()
        if len(ranges_raw) < 1 or len(ranges_raw) > 32:
            raise ConfigError()
        total_positions += len(ranges_raw)
        if total_positions > 16384:
            raise ConfigError()
        ranges = []
        for rg in ranges_raw:
            if not isinstance(rg, list) or len(rg) != 2:
                raise ConfigError()
            lo = _req_int(rg[0], -2048, 2048)
            hi = _req_int(rg[1], -2048, 2048)
            if lo > hi:
                raise ConfigError()
            ranges.append((lo, hi))
        rules.append((rid, rcls, rprio, ranges))

    # fallback tree
    fb = cfg["fallback"]
    node_count = [0]
    max_depth = [0]

    def walk(node, depth):
        if depth > 16:
            raise ConfigError()
        if not isinstance(node, dict):
            raise ConfigError()
        node_count[0] += 1
        if node_count[0] > 255:
            raise ConfigError()
        keys = set(node.keys())
        if keys == {"class"}:
            _req_int(node["class"], 0, 65535)
            if depth > max_depth[0]:
                max_depth[0] = depth
            return
        if keys == {"feature", "threshold", "le", "gt"}:
            J = _req_int(node["feature"], 0, W - 1)
            Z = _req_int(node["threshold"], -2048, 2048)
            walk(node["le"], depth + 1)
            walk(node["gt"], depth + 1)
            return
        raise ConfigError()

    walk(fb, 0)

    return {
        "idle_timeout": idle_timeout,
        "packet_limit": packet_limit,
        "prefix_width": W,
        "rules": rules,
        "fallback": fb,
    }


def program_from_config(cfg):
    return {
        "idle_timeout": cfg["idle_timeout"],
        "packet_limit": cfg["packet_limit"],
        "prefix_width": cfg["prefix_width"],
        "rules": [[rid, rcls, rprio, [[lo, hi] for lo, hi in ranges]]
                  for (rid, rcls, rprio, ranges) in cfg["rules"]],
        "fallback": cfg["fallback"],
    }


# ---------------------------------------------------------------------------
# Runtime
# ---------------------------------------------------------------------------
class EventError(Exception):
    pass


class Flow(object):
    __slots__ = ("fid", "last", "n", "fwd", "decided", "cls", "reason",
                 "rule", "mcount", "first", "lastfeat", "active")

    def __init__(self):
        self.fid = 0
        self.last = 0
        self.n = 0
        self.fwd = None
        self.decided = False
        self.cls = None
        self.reason = None
        self.rule = None
        self.mcount = 0
        self.first = []
        self.lastfeat = []
        self.active = []


REASON_CODE = {"key": 0, "idle": 1, "packet_limit": 2, "end": 3}
CODE_REASON = {0: "key", 1: "idle", 2: "packet_limit", 3: "end"}


class Engine(object):
    def __init__(self, prog):
        self.idle_timeout = prog["idle_timeout"]
        self.packet_limit = prog["packet_limit"]
        self.W = prog["prefix_width"]

        # Build trie
        self.children = [[]]      # list of (lo, hi, child)
        self.edge_map = [{}]      # (lo,hi) -> child
        self.terminal = [[]]      # list of (rid, prio, cls)
        self.depth = [0]
        self.maxlen = 0

        for (rid, rcls, rprio, ranges) in prog["rules"]:
            node = 0
            for (lo, hi) in ranges:
                key = (lo, hi)
                mp = self.edge_map[node]
                nxt = mp.get(key)
                if nxt is None:
                    nxt = len(self.children)
                    mp[key] = nxt
                    self.children.append([])
                    self.edge_map.append({})
                    self.terminal.append([])
                    d = self.depth[node] + 1
                    self.depth.append(d)
                    if d > self.maxlen:
                        self.maxlen = d
                    self.children[node].append((lo, hi, nxt))
                node = nxt
            self.terminal[node].append((rid, rprio, rcls))

        # Build query indexes for nodes with many children
        self.qindex = [None] * len(self.children)
        for i, ch in enumerate(self.children):
            if len(ch) > 4:
                items = sorted(ch, key=lambda x: x[0])
                los = [it[0] for it in items]
                n = len(items)
                size = 1
                while size < n:
                    size <<= 1
                NEG = -10**9
                seg = [NEG] * (2 * size)
                for idx, it in enumerate(items):
                    seg[size + idx] = it[1]
                for idx in range(size - 1, 0, -1):
                    a = seg[2 * idx]
                    b = seg[2 * idx + 1]
                    seg[idx] = a if a >= b else b
                self.qindex[i] = (los, items, seg, size)

        # Compile fallback tree to arrays
        self.tree = []
        self.tree_root = self._build_tree(prog["fallback"])

        # Mutable state
        self.flows = {}
        self.heap = []
        self.last_time = -1

    # -- trie query ---------------------------------------------------------
    def _query(self, node, v):
        ch = self.children[node]
        if not ch:
            return ()
        if len(ch) <= 4:
            out = []
            for lo, hi, c in ch:
                if lo <= v <= hi:
                    out.append(c)
            return out
        los, items, seg, size = self.qindex[node]
        j = bisect_right(los, v)
        if j == 0:
            return ()
        res = []
        stack = [(1, 0, size)]
        while stack:
            ni, l, r = stack.pop()
            if l >= j:
                continue
            if seg[ni] < v:
                continue
            if r - l == 1:
                res.append(items[l][2])
            else:
                m = (l + r) >> 1
                stack.append((ni << 1, l, m))
                stack.append((ni << 1 | 1, m, r))
        return res

    def _replay(self, feats):
        S = []
        for v in feats:
            new = list(self._query(0, v))
            for s in S:
                new.extend(self._query(s, v))
            S = new
        return S

    # -- fallback tree ------------------------------------------------------
    def _build_tree(self, node):
        keys = node.keys()
        if "class" in keys:
            idx = len(self.tree)
            self.tree.append(("c", node["class"]))
            return idx
        # reserve slot then build children
        idx = len(self.tree)
        self.tree.append(None)
        le = self._build_tree(node["le"])
        gt = self._build_tree(node["gt"])
        self.tree[idx] = ("i", node["feature"], node["threshold"], le, gt)
        return idx

    def _tree_eval(self, feats):
        i = self.tree_root
        tree = self.tree
        while True:
            nd = tree[i]
            if nd[0] == "c":
                return nd[1]
            if feats[nd[1]] <= nd[2]:
                i = nd[3]
            else:
                i = nd[4]

    def backup_class(self, f):
        feats = f.first
        need = self.W - len(feats)
        if need > 0:
            feats = feats + [0] * need
        return self._tree_eval(feats)

    # -- heap ---------------------------------------------------------------
    def _rebuild_heap(self):
        self.heap = [(f.last, fid) for fid, f in self.flows.items()
                     if not f.decided]
        heapq.heapify(self.heap)

    # -- expiry -------------------------------------------------------------
    def expire(self, T):
        thr = T - self.idle_timeout
        heap = self.heap
        expired = []
        while heap and heap[0][0] < thr:
            la, fid = heapq.heappop(heap)
            f = self.flows.get(fid)
            if f is None or f.decided:
                continue
            if f.last != la:
                continue
            expired.append(fid)
        if not expired:
            return []
        if len(expired) > 1:
            expired.sort()
        ev = []
        for fid in expired:
            f = self.flows.get(fid)
            if f is None or f.decided:
                continue
            cls = self.backup_class(f)
            f.decided = True
            f.cls = cls
            f.reason = "idle"
            f.rule = None
            ev.append({"type": "decision", "flow": fid, "class": cls,
                       "reason": "idle", "at": f.n, "time": T, "rule": None})
        return ev

    # -- packet processing --------------------------------------------------
    def add_packet(self, f, source, length, T):
        if f.fwd is None:
            f.fwd = source
        v = length if source == f.fwd else -length
        f.n += 1
        f.last = T
        if len(f.first) < self.W:
            f.first.append(v)
        events = []

        if self.maxlen:
            lf = f.lastfeat
            lf.append(v)
            if len(lf) > self.maxlen:
                del lf[0]

            new = list(self._query(0, v))
            for s in f.active:
                new.extend(self._query(s, v))
            f.active = new

            matched = None
            for s in new:
                term = self.terminal[s]
                if term:
                    d = self.depth[s]
                    if matched is None:
                        matched = []
                    for (rid, prio, cls) in term:
                        matched.append((rid, prio, cls, d))

            if matched is not None:
                matched.sort(key=lambda x: x[0])
                for (rid, prio, cls, d) in matched:
                    events.append({"type": "match", "flow": f.fid, "rule": rid,
                                   "start": f.n - d, "end": f.n})
                    f.mcount += 1

                if not f.decided:
                    best = None
                    for (rid, prio, cls, d) in matched:
                        key = (prio, d, -rid)
                        if best is None or key > best[0]:
                            best = (key, rid, cls, d)
                    _, brid, bcls, bd = best
                    f.decided = True
                    f.cls = bcls
                    f.reason = "key"
                    f.rule = brid
                    events.append({"type": "decision", "flow": f.fid,
                                   "class": bcls, "reason": "key", "at": f.n,
                                   "time": T, "rule": brid})

        if not f.decided and f.n >= self.packet_limit:
            cls = self.backup_class(f)
            f.decided = True
            f.cls = cls
            f.reason = "packet_limit"
            f.rule = None
            events.append({"type": "decision", "flow": f.fid, "class": cls,
                           "reason": "packet_limit", "at": f.n, "time": T,
                           "rule": None})

        if not f.decided:
            heapq.heappush(self.heap, (T, f.fid))
            if len(self.heap) > 8192:
                self._rebuild_heap()
        return events

    # -- request handling ---------------------------------------------------
    def handle(self, req, first):
        if not isinstance(req, dict):
            raise EventError()
        op = req.get("op")
        if not isinstance(op, str):
            raise EventError()

        if op == "restore":
            if not first:
                raise EventError()
            if set(req.keys()) != {"op", "checkpoint"}:
                raise EventError()
            self._restore(req["checkpoint"])
            return {"events": []}

        if op == "checkpoint":
            if set(req.keys()) != {"op"}:
                raise EventError()
            return {"checkpoint": self._checkpoint()}

        if op == "open":
            if set(req.keys()) != {"op", "flow", "time"}:
                raise EventError()
            fid = req["flow"]
            T = req["time"]
            if not is_int(fid) or not (0 <= fid <= INT32_MAX):
                raise EventError()
            if not is_int(T) or not (0 <= T <= TIME_MAX):
                raise EventError()
            if T < self.last_time:
                raise EventError()
            if fid in self.flows:
                raise EventError()
            if len(self.flows) >= 4096:
                raise EventError()
            events = self.expire(T)
            f = Flow()
            f.fid = fid
            f.last = T
            self.flows[fid] = f
            heapq.heappush(self.heap, (T, fid))
            self.last_time = T
            return {"events": events}

        if op == "tick":
            if set(req.keys()) != {"op", "time"}:
                raise EventError()
            T = req["time"]
            if not is_int(T) or not (0 <= T <= TIME_MAX):
                raise EventError()
            if T < self.last_time:
                raise EventError()
            events = self.expire(T)
            self.last_time = T
            return {"events": events}

        if op == "close":
            if set(req.keys()) != {"op", "flow", "time"}:
                raise EventError()
            fid = req["flow"]
            T = req["time"]
            if not is_int(fid) or not (0 <= fid <= INT32_MAX):
                raise EventError()
            if not is_int(T) or not (0 <= T <= TIME_MAX):
                raise EventError()
            if T < self.last_time:
                raise EventError()
            f = self.flows.get(fid)
            if f is None:
                raise EventError()
            events = self.expire(T)
            # f might have been decided by expiry; otherwise decide end
            if not f.decided:
                cls = self.backup_class(f)
                f.decided = True
                f.cls = cls
                f.reason = "end"
                f.rule = None
                events.append({"type": "decision", "flow": fid, "class": cls,
                               "reason": "end", "at": f.n, "time": T,
                               "rule": None})
            events.append({"type": "closed", "flow": fid, "packets": f.n,
                           "matches": f.mcount, "class": f.cls,
                           "reason": f.reason, "rule": f.rule})
            del self.flows[fid]
            self.last_time = T
            return {"events": events}

        if op == "chunk":
            if set(req.keys()) != {"op", "packets"}:
                raise EventError()
            packets = req["packets"]
            if not isinstance(packets, list):
                raise EventError()
            if len(packets) > 1024:
                raise EventError()
            events = []
            for p in packets:
                if not isinstance(p, dict):
                    raise EventError()
                if set(p.keys()) != {"flow", "time", "source", "length"}:
                    raise EventError()
                fid = p["flow"]
                t = p["time"]
                src = p["source"]
                L = p["length"]
                if not is_int(fid) or not (0 <= fid <= INT32_MAX):
                    raise EventError()
                if not is_int(t) or not (0 <= t <= TIME_MAX):
                    raise EventError()
                if not is_int(src) or (src != 0 and src != 1):
                    raise EventError()
                if not is_int(L) or not (1 <= L <= 2048):
                    raise EventError()
                if t < self.last_time:
                    raise EventError()
                f = self.flows.get(fid)
                if f is None:
                    raise EventError()
                ev = self.expire(t)
                if ev:
                    events.extend(ev)
                ev = self.add_packet(f, src, L, t)
                if ev:
                    events.extend(ev)
                self.last_time = t
            return {"events": events}

        raise EventError()

    # -- checkpoint / restore ----------------------------------------------
    def _checkpoint(self):
        fl = []
        for fid, f in self.flows.items():
            fl.append([
                f.fid, f.last, f.n,
                -1 if f.fwd is None else f.fwd,
                1 if f.decided else 0,
                -1 if f.cls is None else f.cls,
                -1 if f.reason is None else REASON_CODE[f.reason],
                -1 if f.rule is None else f.rule,
                f.mcount,
                list(f.first),
                list(f.lastfeat),
            ])
        return {"t": self.last_time, "fl": fl}

    def _restore(self, val):
        if not isinstance(val, dict):
            raise EventError()
        if set(val.keys()) != {"t", "fl"}:
            raise EventError()
        t = val["t"]
        fl = val["fl"]
        if not is_int(t):
            raise EventError()
        if not isinstance(fl, list):
            raise EventError()
        self.flows = {}
        self.heap = []
        self.last_time = t
        for e in fl:
            if not isinstance(e, list) or len(e) != 11:
                raise EventError()
            f = Flow()
            f.fid = e[0]
            f.last = e[1]
            f.n = e[2]
            f.fwd = None if e[3] == -1 else e[3]
            f.decided = bool(e[4])
            f.cls = None if e[5] == -1 else e[5]
            f.reason = None if e[6] == -1 else CODE_REASON[e[6]]
            f.rule = None if e[7] == -1 else e[7]
            f.mcount = e[8]
            f.first = list(e[9])
            f.lastfeat = list(e[10])
            if self.maxlen:
                f.active = self._replay(f.lastfeat)
            else:
                f.active = []
            self.flows[f.fid] = f
            if not f.decided:
                heapq.heappush(self.heap, (f.last, f.fid))


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------
def cmd_compile():
    try:
        raw = sys.stdin.buffer.read()
    except Exception:
        sys.stdout.write('{"error":"config"}')
        return 2
    try:
        text = raw.decode("utf-8")
    except Exception:
        sys.stdout.write('{"error":"config"}')
        return 2
    try:
        cfg = parse_json_text(text)
    except Exception:
        sys.stdout.write('{"error":"config"}')
        return 2
    try:
        validated = validate_config(cfg)
    except ConfigError:
        sys.stdout.write('{"error":"config"}')
        return 2
    except Exception:
        sys.stdout.write('{"error":"config"}')
        return 2
    prog = program_from_config(validated)
    out = json.dumps(prog, separators=(",", ":"))
    sys.stdout.write(out)
    return 0


def cmd_stream(path):
    try:
        with open(path, "r", encoding="utf-8") as fh:
            prog = json.load(fh)
    except Exception:
        return 2
    engine = Engine(prog)

    stdin = sys.stdin.buffer
    stdout = sys.stdout
    first = True

    while True:
        line = stdin.readline()
        if not line:
            break
        try:
            text = line.decode("utf-8")
        except Exception:
            stdout.write('{"error":"event"}\n')
            stdout.flush()
            return 2
        stripped = text.strip()
        if stripped == "":
            stdout.write('{"error":"event"}\n')
            stdout.flush()
            return 2
        try:
            req = parse_json_text(text)
        except Exception:
            stdout.write('{"error":"event"}\n')
            stdout.flush()
            return 2
        try:
            resp = engine.handle(req, first)
        except EventError:
            stdout.write('{"error":"event"}\n')
            stdout.flush()
            return 2
        except Exception:
            stdout.write('{"error":"event"}\n')
            stdout.flush()
            return 2
        first = False
        stdout.write(json.dumps(resp, separators=(",", ":")))
        stdout.write("\n")
        stdout.flush()
    return 0


def main():
    args = sys.argv
    if len(args) >= 2 and args[1] == "compile":
        return cmd_compile()
    if len(args) == 3 and args[1] == "stream":
        return cmd_stream(args[2])
    return 2


if __name__ == "__main__":
    raise SystemExit(main())
